use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,process::Command,collections::BTreeMap};const R:&str="/home/ubuntu/src/zopro-perf-work/g2-two-chain-stream176";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){fs::create_dir(format!("{R}/linked-code")).unwrap();let mut all=BTreeMap::<String,Value>::new();for(label,binary)in[("frozen","control-bin"),("OFF","candidate-bin"),("ON","candidate-bin")]{let binary=format!("{R}/{binary}");let nm=Command::new("nm").args(["-S","--size-sort",&binary]).output().unwrap();assert!(nm.status.success());let text=String::from_utf8(nm.stdout).unwrap();let symbols=text.lines().filter_map(|l|{let f=l.split_whitespace().collect::<Vec<_>>();if f.len()!=4{return None;}let raw=f[3];let demangled=rustc_demangle::try_demangle(raw).map(|x|format!("{x:#}")).unwrap_or(raw.into());let wanted=if label=="ON"{"::msm::two_chain_stream::apply::<"}else{"::msm::g2_borrowed::apply::<"};if demangled.contains(wanted)||demangled.contains("::msm::stream_g1_impl::<"){Some((raw.to_owned(),demangled,u64::from_str_radix(f[1],16).unwrap()))}else{None}}).collect::<Vec<_>>();assert_eq!(symbols.len(),2);let mut rows=vec![];for(raw,demangled,size)in symbols{let kind=if demangled.contains("stream_g1_impl"){"G1"}else{"G2"};let out=Command::new("objdump").args(["-d","--no-show-raw-insn",&format!("--disassemble={raw}"),&binary]).output().unwrap();assert!(out.status.success());let s=String::from_utf8(out.stdout).unwrap();let path=format!("linked-code/{label}-{kind}.txt");fs::write(format!("{R}/{path}"),&s).unwrap();let(mut instructions,mut ifma,mut rsp,mut sub)=(0,0,0,0u64);for line in s.lines(){let Some((address,tail))=line.trim().split_once(':')else{continue};if address.is_empty()||!address.chars().all(|c|c.is_ascii_hexdigit()){continue;}let mut fields=tail.split_whitespace();let Some(mnemonic)=fields.next()else{continue};instructions+=1;if mnemonic.starts_with("vpmadd52"){ifma+=1;}if tail.contains("(%rsp)"){rsp+=1;}let args=fields.collect::<Vec<_>>().join("");if mnemonic=="sub"&&args.ends_with(",%rsp"){if let Some(value)=args.strip_prefix("$0x"){sub+=u64::from_str_radix(value.trim_end_matches(",%rsp"),16).unwrap();}}}rows.push(json!({"kind":kind,"symbol":demangled,"bytes":size,"instruction_sites":instructions,"IFMA_sites":ifma,"RSP_operand_lines":rsp,"literal_stack_subtraction_sum":sub,"assembly":path,"assembly_sha256":hash(&format!("{R}/{path}"))}));}all.insert(label.into(),json!({"binary_sha256":hash(&binary),"functions":rows}));}fs::write(format!("{R}/codegen.json"),serde_json::to_vec_pretty(&json!({"variants":all,"static_counts_are_not_dynamic_spills_or_frame_bounds":true})).unwrap()).unwrap();println!("Linked code mapped:original/fresh/twochainG2+unchangedG1;all6 disassemblies hash-bound");}
